package org.local.donusturucu.qa;
import android.os.Bundle;import android.content.Context;import android.graphics.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
public class LargeImages extends OcrRobustness {
 File copy(String name,File root)throws Exception{File f=new File(root,name);InputStream in=getContext().getAssets().open(name);OutputStream out=new FileOutputStream(f);try{byte[]b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}finally{in.close();out.close();}return f;}
 void verify(Object doc,Class<?>type)throws Exception{Field blocks=type.getDeclaredField("blocks");blocks.setAccessible(true);StringBuilder text=new StringBuilder();int images=0;for(Object block:(List<?>)blocks.get(doc)){Field tf=block.getClass().getDeclaredField("text"),im=block.getClass().getDeclaredField("image");tf.setAccessible(true);im.setAccessible(true);Object s=tf.get(block);if(s!=null)text.append(s).append('\n');byte[]data=(byte[])im.get(block);if(data!=null){images++;Bitmap bmp=BitmapFactory.decodeByteArray(data,0,data.length);try{if(bmp.getWidth()!=3200||bmp.getHeight()!=2400||bmp.getPixel(800,1200)!=Color.RED||bmp.getPixel(2400,1200)!=Color.BLUE)throw new IOException("Image pixels changed");}finally{bmp.recycle();}}}String t=text.toString();if(images!=1||!t.contains("Merhaba Silav ABC-42")||!t.contains("مرحبا بالعالم")||!t.contains("سلام دنیا")||t.indexOf("Merhaba")>t.indexOf("مرحبا")||t.indexOf("مرحبا")>t.indexOf("سلام"))throw new IOException("Image/text/order mismatch: "+t);}
 public void onStart(){Bundle result=new Bundle();try{
  Context target=getTargetContext();ClassLoader loader=target.getClassLoader();Class<?>type=Class.forName("org.local.donusturucu.RichDocument",true,loader),host=Class.forName("org.local.donusturucu.RichDocument$Host",true,loader);Method read=type.getDeclaredMethod("read",File.class,String.class,host),write=type.getDeclaredMethod("write",String.class,File.class,host);read.setAccessible(true);write.setAccessible(true);Object callback=Proxy.newProxyInstance(loader,new Class<?>[]{host},new InvocationHandler(){public Object invoke(Object p,Method m,Object[]args){return null;}});File root=new File(target.getExternalFilesDir(null),"large-rich-chains");root.mkdirs();JSONArray rows=new JSONArray();
  for(int repeat=1;repeat<=3;repeat++)for(String source:new String[]{"large.html","large.epub"}){JSONObject row=new JSONObject();row.put("source",source);row.put("repeat",repeat);try{File f=copy(source,root);String before=hash(f),ext=source.endsWith("html")?"html":"epub";
   if(!source.startsWith("large")){boolean rejected=false;try{read.invoke(null,f,ext,callback);}catch(InvocationTargetException e){if(!(e.getCause() instanceof IOException))throw e;rejected=true;}if(!rejected)throw new IOException("Unsafe/broken input accepted");row.put("rejected",true);}
   else{Object doc=read.invoke(null,f,ext,callback);verify(doc,type);String[]steps=ext.equals("html")?new String[]{"docx","epub","html"}:new String[]{"odt","docx","html"};for(int index=0;index<steps.length;index++){File folder=new File(root,source+"-"+repeat+"-"+index);folder.mkdirs();File out=(File)write.invoke(doc,steps[index],folder,callback);doc=read.invoke(null,out,steps[index],callback);verify(doc,type);row.put("output",out.toString());}row.put("chain",Arrays.toString(steps));row.put("exact_image_pixels",true);row.put("rtl_text_and_order_preserved",true);}
   if(!before.equals(hash(f)))throw new IOException("Source changed");row.put("source_unchanged",true);row.put("pass",true);
  }catch(Throwable e){row.put("pass",false);row.put("error",e.toString());if(e instanceof InvocationTargetException)row.put("cause",((InvocationTargetException)e).getCause().toString());}rows.put(row);JSONObject report=new JSONObject();report.put("cases",rows.length());int failures=0;for(int i=0;i<rows.length();i++)if(!rows.getJSONObject(i).getBoolean("pass"))failures++;report.put("failures",failures);report.put("rows",rows);Writer w=new OutputStreamWriter(new FileOutputStream(new File(root,"report.json")),"UTF-8");try{w.write(report.toString(2));}finally{w.close();}}
  result.putString("report",new File(root,"report.json").toString());finish(0,result);
 }catch(Throwable e){result.putString("error",e.toString());finish(1,result);}}
}
